drop function if exists public.search_ghana_localities(text, text, integer);

create table if not exists public.ghana_localities (
  geoname_id bigint primary key,
  name text not null,
  region text not null,
  district text,
  latitude double precision not null,
  longitude double precision not null,
  population bigint not null default 0,
  feature_code text not null,
  normalized_name text not null,
  normalized_aliases text[] not null default '{}'::text[],
  normalized_region text not null,
  search_text text not null,
  rank_weight integer not null default 0,
  refreshed_at timestamptz not null default timezone('utc'::text, now())
);

alter table public.ghana_localities enable row level security;

create index if not exists idx_ghana_localities_region_rank
  on public.ghana_localities (normalized_region, rank_weight desc, population desc, name);

create index if not exists idx_ghana_localities_name
  on public.ghana_localities (normalized_name, region);

